#!/usr/bin/env node

const fs = require("fs");
const path = require("path");
const { execSync } = require("child_process");
const readline = require("readline");

const API_ENDPOINT = "https://api.codemax.pro";

// ── Colors ──
const c = {
    reset: "\x1b[0m",
    bold: "\x1b[1m",
    dim: "\x1b[2m",
    cyan: "\x1b[36m",
    green: "\x1b[32m",
    yellow: "\x1b[33m",
    red: "\x1b[31m",
    gray: "\x1b[90m",
    white: "\x1b[97m",
};

const log = (msg) => console.log(msg);
const ok = (msg) => log(`  ${c.green}✓ ${msg}${c.reset}`);
const warn = (msg) => log(`  ${c.yellow}⚠ ${msg}${c.reset}`);
const fail = (msg) => log(`  ${c.red}✗ ${msg}${c.reset}`);
const info = (msg) => log(`  ${c.cyan}${msg}${c.reset}`);
const gray = (msg) => log(`  ${c.gray}${msg}${c.reset}`);

function ask(question) {
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
    return new Promise((resolve) => {
        rl.question(question, (answer) => {
            rl.close();
            resolve(answer.trim());
        });
    });
}

function readJson(filePath) {
    try {
        if (fs.existsSync(filePath)) {
            const raw = fs.readFileSync(filePath, "utf8").trim();
            if (!raw) return {};
            return JSON.parse(raw);
        }
    } catch {}
    return {};
}

function writeJson(filePath, data) {
    const dir = path.dirname(filePath);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(filePath, JSON.stringify(data, null, 2), "utf8");
}

function which(cmd) {
    try {
        const r = execSync(process.platform === "win32" ? `where ${cmd}` : `which ${cmd}`, {
            encoding: "utf8",
            stdio: "pipe",
        }).trim();
        return r ? true : false;
    } catch {
        return false;
    }
}

async function validateKey(apiKey) {
    const body = JSON.stringify({
        model: "claude-opus-5-5",
        max_tokens: 10,
        messages: [{ role: "user", content: "Hi" }],
    });

    try {
        const res = await fetch(`${API_ENDPOINT}/v1/messages`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "x-api-key": apiKey,
                "anthropic-version": "2023-06-01",
            },
            body,
            signal: AbortSignal.timeout(30000),
        });

        if (res.ok) return { valid: true };
        if (res.status === 429) return { valid: true, rateLimit: true };
        if (res.status === 401 || res.status === 403) return { valid: false, reason: "Invalid API key" };
        if (res.status === 402) return { valid: false, reason: "No remaining balance" };
        return { valid: false, reason: `Server returned ${res.status}` };
    } catch (e) {
        return { valid: false, reason: e.message, network: true };
    }
}

async function main() {
    log("");
    log(`  ${c.cyan}╔══════════════════════════════════════════╗${c.reset}`);
    log(`  ${c.cyan}║     ${c.bold}CodeMax × OpenCode Setup${c.reset}${c.cyan}            ║${c.reset}`);
    log(`  ${c.cyan}╚══════════════════════════════════════════╝${c.reset}`);
    log("");

    const home = process.env.HOME || process.env.USERPROFILE;
    if (!home) {
        fail("Cannot determine home directory");
        process.exit(1);
    }

    // ── Get API Key ──
    let apiKey = process.argv[2] || "";
    if (!apiKey) {
        log(`  ${c.white}Enter your CodeMax API key${c.reset}`);
        gray("Get it from your admin or codemax.pro");
        log("");
        apiKey = await ask(`  ${c.white}API Key: ${c.reset}`);
        log("");
    }

    if (!apiKey || apiKey.length < 5) {
        fail("No valid API key provided. Exiting.");
        process.exit(1);
    }

    // ── [1/4] Validate API Key ──
    info("[1/4] Validating API key...");
    const result = await validateKey(apiKey);

    if (result.valid) {
        if (result.rateLimit) {
            warn("API key valid but rate-limited. Continuing setup...");
        } else {
            ok("API key is valid!");
            ok("Connected to CodeMax");
        }
    } else if (result.network) {
        warn(`Could not reach server: ${result.reason}`);
        const cont = await ask(`  ${c.yellow}Continue anyway? (y/n): ${c.reset}`);
        if (cont.toLowerCase() !== "y") process.exit(1);
    } else {
        fail(result.reason);
        gray("Make sure you're using a valid CodeMax API key (sk-cp-...)");
        process.exit(1);
    }
    log("");

    // ── [2/4] Check OpenCode ──
    info("[2/4] Checking OpenCode...");
    if (which("opencode")) {
        ok("OpenCode is installed");
    } else {
        warn("OpenCode not found.");
        if (process.platform === "win32") {
            gray('Install: powershell -c "irm https://opencode.ai/install.ps1 | iex"');
        } else {
            gray("Install: curl -fsSL https://opencode.ai/install.sh | bash");
        }
        const cont = await ask(`  ${c.yellow}Continue setup anyway? (y/n): ${c.reset}`);
        if (cont.toLowerCase() !== "y") process.exit(1);
    }
    log("");

    // ── [3/4] Configure OpenCode — Global config ──
    info("[3/4] Configuring OpenCode with CodeMax provider...");

    const configDir = path.join(home, ".config", "opencode");
    const configPath = path.join(configDir, "opencode.json");

    try {
        const config = readJson(configPath);

        config["$schema"] = "https://opencode.ai/config.json";

        // Set up anthropic provider with custom base URL
        if (!config.provider) config.provider = {};

        config.provider.anthropic = {
            options: {
                baseURL: `${API_ENDPOINT}/v1`,
                apiKey: apiKey,
            },
            // NOTE: `attachment: true` is REQUIRED — without it OpenCode marks the
            // model as not supporting image/file input and refuses to send images,
            // emitting "this model does not support image input" client-side (the
            // image never reaches the API). `tool_call: true` keeps agent tools on.
            models: {
                "claude-opus-5-5": {
                    name: "Claude Opus 5.5",
                    attachment: true,
                    tool_call: true,
                    limit: { context: 1000000, output: 32768 },
                },
                "claude-opus-5-5-thinking": {
                    name: "Claude Opus 5.5 (Thinking)",
                    attachment: true,
                    tool_call: true,
                    limit: { context: 1000000, output: 32768 },
                },
                "claude-fable-5-1": {
                    name: "Claude Fable 5.1",
                    attachment: true,
                    tool_call: true,
                    limit: { context: 1000000, output: 32768 },
                },
                "claude-fable-5-1-thinking": {
                    name: "Claude Fable 5.1 (Thinking)",
                    attachment: true,
                    tool_call: true,
                    limit: { context: 1000000, output: 32768 },
                },
                "claude-sonnet-5-5": {
                    name: "Claude Sonnet 5.5",
                    attachment: true,
                    tool_call: true,
                    limit: { context: 1000000, output: 32768 },
                },
                "claude-sonnet-5-5-thinking": {
                    name: "Claude Sonnet 5.5 (Thinking)",
                    attachment: true,
                    tool_call: true,
                    limit: { context: 1000000, output: 32768 },
                },
                "claude-haiku-5-5": {
                    name: "Claude Haiku 5.5",
                    attachment: true,
                    tool_call: true,
                    limit: { context: 200000, output: 32768 },
                },
            },
        };

        writeJson(configPath, config);
        ok(`Config saved: ${configPath}`);
    } catch (e) {
        fail(`Failed to write config: ${e.message}`);
    }
    log("");

    // ── [4/4] Store auth credentials ──
    info("[4/4] Storing auth credentials...");

    const authDir = path.join(home, ".local", "share", "opencode");
    if (process.platform === "win32") {
        // Windows: use AppData
        const appData = process.env.LOCALAPPDATA || path.join(home, "AppData", "Local");
        const winAuthDir = path.join(appData, "opencode");
        const authPath = path.join(winAuthDir, "auth.json");
        try {
            const auth = readJson(authPath);
            auth.anthropic = { apiKey: apiKey };
            writeJson(authPath, auth);
            ok(`Auth saved: ${authPath}`);
        } catch (e) {
            warn(`Could not save auth: ${e.message}`);
            gray("You can authenticate manually with /connect inside OpenCode");
        }
    } else {
        const authPath = path.join(authDir, "auth.json");
        try {
            const auth = readJson(authPath);
            auth.anthropic = { apiKey: apiKey };
            writeJson(authPath, auth);
            ok(`Auth saved: ${authPath}`);
        } catch (e) {
            warn(`Could not save auth: ${e.message}`);
            gray("You can authenticate manually with /connect inside OpenCode");
        }
    }

    // ── Done ──
    log("");
    log(`  ${c.green}╔══════════════════════════════════════════╗${c.reset}`);
    log(`  ${c.green}║       ${c.bold}✓ Setup complete!${c.reset}${c.green}                  ║${c.reset}`);
    log(`  ${c.green}╚══════════════════════════════════════════╝${c.reset}`);
    log("");
    log(`  ${c.white}What was configured:${c.reset}`);
    gray(`  • API key validated`);
    gray(`  • Anthropic provider → CodeMax endpoint`);
    gray(`  • 7 Claude models registered`);
    gray(`  • Auth credentials stored`);
    log("");
    log(`  ${c.gray}╭───────────────────────────────────────╮${c.reset}`);
    log(`  ${c.gray}│  Provider:  anthropic (via CodeMax)   │${c.reset}`);
    log(`  ${c.gray}│  Base URL:  api.codemax.pro           │${c.reset}`);
    log(`  ${c.gray}│  Key:       ${apiKey.substring(0, 12)}...           │${c.reset}`);
    log(`  ${c.gray}│  Models:    Opus 5.5, Fable 5.1,      │${c.reset}`);
    log(`  ${c.gray}│             Sonnet 5.5, Haiku 5.5     │${c.reset}`);
    log(`  ${c.gray}╰───────────────────────────────────────╯${c.reset}`);
    log("");
    gray("Use /models inside OpenCode to switch models.");
    gray("Re-run anytime to update your key.");
    log("");

    // Ask to launch
    if (which("opencode")) {
        const launch = await ask(`  ${c.white}Launch OpenCode now? (y/n): ${c.reset}`);
        if (launch.toLowerCase() === "y" || launch === "") {
            log("");
            info("Launching OpenCode...");
            log(`  ${c.gray}════════════════════════════════════${c.reset}`);
            log("");
            try {
                execSync("opencode", { stdio: "inherit" });
            } catch {}
        } else {
            log("");
            log(`  ${c.white}To start later, open any terminal and type: opencode${c.reset}`);
            log("");
        }
    }
}

main().catch((e) => {
    fail(`Unexpected error: ${e.message}`);
    process.exit(1);
});
